public IList<string> GenerateParenthesis(int n)
{
    var result = new List<string>();
    var current = new System.Text.StringBuilder();

    void Dfs(int open, int close)
    {
        if (current.Length == 2 * n) { result.Add(current.ToString()); return; }
        if (open < n)                       // can still add an opening
        {
            current.Append('(');
            Dfs(open + 1, close);
            current.Length--;              // backtrack
        }
        if (close < open)                   // can add a closing without breaking validity
        {
            current.Append(')');
            Dfs(open, close + 1);
            current.Length--;              // backtrack
        }
    }

    Dfs(0, 0);
    return result;
}
